package org.apache.commons.lang3;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.ObjectStreamClass;
import java.io.OutputStream;
import java.io.Serializable;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.apache.commons.lang3.SerializationUtils.ClassLoaderAwareObjectInputStream;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class ClassLoaderAwareObjectInputStream_resolveClass_TriageGen2Test {

    /**
     * Helper method to access the protected resolveClass method via reflection.
     */
    @SuppressWarnings("unchecked")
    private Class<?> invokeResolveClass(ClassLoaderAwareObjectInputStream stream, ObjectStreamClass desc) throws Exception {
        Method method = ClassLoaderAwareObjectInputStream.class.getDeclaredMethod("resolveClass", ObjectStreamClass.class);
        method.setAccessible(true);
        return (Class<?>) method.invoke(stream, desc);
    }

    /**
     * Test Case 1: Success via the provided classLoader.
     * This covers the 'try' block success path.
     */
    @Test
    public void testResolveClass_SuccessWithProvidedClassLoader() throws Exception {
        // Use a real class that is guaranteed to be in the provided classloader (System/App classloader)
        String className = String.class.getName();
        ClassLoader classLoader = String.class.getClassLoader();

        InputStream in = new ByteArrayInputStream(new byte[0]);
        ClassLoaderAwareObjectInputStream stream = new ClassLoaderAwareObjectInputStream(in, classLoader);

        ObjectStreamClass desc = mock(ObjectStreamClass.class);
        when(desc.getName()).thenReturn(className);

        Class<?> resolvedClass = invokeResolveClass(stream, desc);

        assertEquals(String.class, resolvedClass);
    }

    /**
     * Test Case 2: Failure in provided classLoader, success in ContextClassLoader.
     * This covers the 'catch' block path.
     */
    @Test
    public void testResolveClass_FallbackToContextClassLoader() throws Exception {
        // We need a class that is NOT in the custom classloader but IS in the ContextClassLoader.
        // Since we can't easily create a custom classloader that lacks standard classes without complex setup,
        // we will mock the behavior by providing a classloader that throws ClassNotFoundException.

        ClassLoader customClassLoader = new ClassLoader() {
            @Override
            public Class<?> loadClass(String name) throws ClassNotFoundException {
                throw new ClassNotFoundException(name);
            }
        };

        // Ensure the ContextClassLoader can find String.class
        ClassLoader originalContextClassLoader = Thread.currentThread().getContextClassLoader();
        Thread.currentThread().setContextClassLoader(String.class.getClassLoader());

        try {
            InputStream in = new ByteArrayInputStream(new byte[0]);
            ClassLoaderAwareObjectInputStream stream = new ClassLoaderAwareObjectInputStream(in, customClassLoader);

            String className = String.class.getName();
            ObjectStreamClass desc = mock(ObjectStreamClass.class);
            when(desc.getName()).thenReturn(className);

            Class<?> resolvedClass = invokeResolveClass(stream, desc);

            assertEquals(String.class, resolvedClass);
        } finally {
            Thread.currentThread().setContextClassLoader(originalContextClassLoader);
        }
    }

    /**
     * Test Case 3: Failure in both classLoaders.
     * This covers the exception propagation path.
     */
    @Test(expected = Exception.class)
    public void testResolveClass_ThrowsExceptionWhenBothFail() throws Exception {
        ClassLoader customClassLoader = new ClassLoader() {
            @Override
            public Class<?> loadClass(String name) throws ClassNotFoundException {
                throw new ClassNotFoundException(name);
            }
        };

        ClassLoader originalContextClassLoader = Thread.currentThread().getContextClassLoader();
        // Set context classloader to a dummy one that won't find the class
        Thread.currentThread().setContextClassLoader(new ClassLoader() {
            @Override
            public Class<?> loadClass(String name) throws ClassNotFoundException {
                throw new ClassNotFoundException(name);
            }
        });

        try {
            InputStream in = new ByteArrayInputStream(new byte[0]);
            ClassLoaderAwareObjectInputStream stream = new ClassLoaderAwareObjectInputStream(in, customClassLoader);

            String className = "non.existent.Class";
            ObjectStreamClass desc = mock(ObjectStreamClass.class);
            when(desc.getName()).thenReturn(className);

            invokeResolveClass(stream, desc);
        } finally {
            Thread.currentThread().setContextClassLoader(originalContextClassLoader);
        }
    }
}

/**
 * Mocking ObjectStreamClass as it's typically part of java.io and hard to mock perfectly without a real stream,
 * but since we are using Mockito, we define the interface requirements here if necessary.
 * However, ObjectStreamClass is a final class in some JDKs. 
 * If the environment prevents mocking ObjectStreamClass, one would use a real ObjectStreamClass 
 * generated from a serialized object.
 */
